func play_combat_event(record):
				var event_class = record.get("event_class", "")
				if event_class == "dot_tick":
								return
				if event_class == "kill":
								var killer = record.get("source")
								if killer == null or not killer.is_player:
												return
				if killer.is_dead:
								return
				var layer = _combat_audio_layer_for(event_class)
				var stream = _combat_audio_stream_for(layer)
				if stream == null:
								return
				var now = OS.get_ticks_msec()
				if _combat_audio_last_played.has(layer) and now - _combat_audio_last_played[layer] < _combat_audio_window_for(layer):
								return
				if layer == "kill" and not _combat_audio_allow_kill_cluster(now):
								return
				_combat_audio_last_played[layer] = now
				play_sound_effect(stream)

func _combat_audio_layer_for(event_class):
				if event_class == "crit":
								return "heavy"
				if event_class == "kill":
								return "kill"
				return "light"

func _combat_audio_stream_for(layer):
				if layer == "heavy":
								return combat_sfx_heavy
				if layer == "kill":
								return combat_sfx_kill
				return combat_sfx_light

func _combat_audio_window_for(layer):
				if layer == "heavy":
								return COMBAT_LAYER_HEAVY_WINDOW_MS
				if layer == "kill":
								return COMBAT_LAYER_KILL_WINDOW_MS
				return COMBAT_LAYER_LIGHT_WINDOW_MS

func _combat_audio_allow_kill_cluster(now):
				if now - _combat_kill_cluster_start > COMBAT_LAYER_KILL_WINDOW_MS:
								_combat_kill_cluster_start = now
								_combat_kill_cluster_count = 0
				_combat_kill_cluster_count += 1
				if _combat_kill_cluster_count > COMBAT_KILL_CLUSTER_THRESHOLD:
								return false
				return _combat_kill_cluster_count == 1

